# ゲーム開始
カード一覧＝[1,1,2,2,3,3]
カード一覧を配列シャッフル。
入力回数＝0。

# 盤面表示用配列
desk＝[]。

# メインループ
while(true){
    # 盤面作成
    desk＝[]。
    for i=0 to 5{
        if(カード一覧[i]=0){
            deskに「👌」を追加。
        }else{
            deskに「■」を追加。
        }
    }
    # プレイヤー入力
    入力＝「1から6までの番号を入力してください（空白で終了）:」と入力。
    if(入力==""){
        # 空白で終了
        break。
    }
    # 入力分割
    番号＝入力を「,」で分割。
    # 入力回数加算
    入力回数＝入力回数+1。
    # 同じ番号チェック
    if(番号[0]=番号[1]){
        「同じ位置のカードは引けません」と表示。
        continue。
    }
    # 範囲チェック
    if(番号[0]<1 or 番号[0]>6 or 番号[1]<1 or 番号[1]>6){
        「番号は1から6の範囲で入力してください」と表示。
        continue。
    }
    # 位置変換（1ベース→0ベース）
    位置1＝番号[0]-1。
    位置2＝番号[1]-1。
    # 正解判定
    if(カード一覧[位置1]=カード一覧[位置2]){
        「正解！」と表示。
        カード一覧[位置1]=0。
        カード一覧[位置2]=0。
    }else{
        「残念」と表示。
    }
    # 盤面表示
    「{入力回数}回目:」と表示。
    deskに「[{カード一覧[位置1]}]」を追加。
    deskに「[{カード一覧[位置2]}]」を追加。
    deskを「-」で連結した文字列を改行付きで表示。
}
# ゲームクリア判定
if(カード一覧の配列合計=0){
    「{入力回数}回目でゲームクリア！」と表示。
}else{
    「ゲーム未クリアのまま終了しました。」と表示。
}
